function SavingsGoalsSection({currency:cur,toast:tst}){
  const [goals,setGoals]=k.useState(()=>{
    try{
      const saved=localStorage.getItem("budget_savings_goals");
      if(saved)return JSON.parse(saved);
    }catch(e){}
    return [
      {id:"g-1",name:"Fonds d'Urgence",target:1000,saved:450,color:"#10b981"},
      {id:"g-2",name:"Voyage & Vacances",target:600,saved:280,color:"#0f67d1"}
    ];
  });
  const [showAdd,setShowAdd]=k.useState(!1);
  const [newName,setNewName]=k.useState("");
  const [newTarget,setNewTarget]=k.useState("");

  const saveGoals=next=>{
    setGoals(next);
    try{localStorage.setItem("budget_savings_goals",JSON.stringify(next));}catch(e){}
  };

  const addGoal=()=>{
    const nm=newName.trim();
    const tg=Number(newTarget);
    if(!nm||!tg||tg<=0){tst("Entrez un nom et un montant cible valide");return;}
    const colors=["#0f67d1","#10b981","#f59e0b","#8b5cf6","#ec4899"];
    const next=[...goals,{id:`g-${Date.now()}`,name:nm,target:tg,saved:0,color:colors[goals.length%colors.length]}];
    saveGoals(next);
    setNewName("");setNewTarget("");setShowAdd(!1);
    tst("Projet d'épargne créé !");
  };

  const deposit=(gId,amount)=>{
    const next=goals.map(g=>{
      if(g.id===gId){
        const nextSaved=Math.max(0,g.saved+amount);
        return {...g,saved:nextSaved};
      }
      return g;
    });
    saveGoals(next);
    tst(amount>0?"Fonds ajoutés à l'objectif !":"Fonds retirés !");
  };

  const deleteGoal=gId=>{
    if(window.confirm("Supprimer ce projet d'épargne ?")){
      saveGoals(goals.filter(g=>g.id!==gId));
      tst("Projet supprimé");
    }
  };

  return o.jsxs("section",{className:"savings-goals-card panel",style:{padding:"24px",marginTop:"16px",background:"var(--surface,#fff)",borderRadius:"16px",border:"1px solid var(--line,rgba(15,23,42,.08))"},children:[
    o.jsxs("div",{style:{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"16px"},children:[
      o.jsxs("div",{children:[
        o.jsx("h2",{style:{fontSize:"16px",fontWeight:"600",color:"var(--ink-1)",margin:"0"},children:"Cagnottes & Projets d'Épargne"}),
        o.jsx("small",{style:{fontSize:"12px",color:"var(--ink-3)"},children:"Suivez vos objectifs d'économies ciblés"})
      ]}),
      o.jsx("button",{className:"primarybtn",style:{padding:"6px 12px",fontSize:"12.5px"},onClick:()=>setShowAdd(!showAdd),children:showAdd?"Fermer":"+ Nouveau Projet"})
    ]}),
    showAdd&&o.jsxs("div",{style:{padding:"14px",background:"var(--selected,rgba(15,23,42,.03))",borderRadius:"10px",marginBottom:"18px",display:"flex",flexDirection:"column",gap:"10px"},children:[
      o.jsx("strong",{style:{fontSize:"13px",color:"var(--ink-1)"},children:"Créer un nouvel objectif d'épargne"}),
      o.jsxs("div",{style:{display:"flex",gap:"8px",flexWrap:"wrap"},children:[
        o.jsx("input",{type:"text",placeholder:"Nom (ex: Ordinateur, Urgence...)",value:newName,onChange:e=>setNewName(e.target.value),style:{flex:"1",minWidth:"180px",padding:"8px 12px",borderRadius:"8px",border:"1px solid var(--line,rgba(15,23,42,.15))",fontSize:"13px"}}),
        o.jsx("input",{type:"number",placeholder:`Montant cible (${cur})`,value:newTarget,onChange:e=>setNewTarget(e.target.value),style:{width:"140px",padding:"8px 12px",borderRadius:"8px",border:"1px solid var(--line,rgba(15,23,42,.15))",fontSize:"13px"}}),
        o.jsx("button",{className:"primarybtn",onClick:addGoal,style:{padding:"8px 14px",fontSize:"13px"},children:"Créer"})
      ]})
    ]}),
    goals.length===0?o.jsx("p",{style:{fontSize:"13px",color:"var(--ink-3)",textAlign:"center",padding:"16px 0"},children:"Aucun projet d'épargne en cours."}):o.jsx("div",{style:{display:"flex",flexDirection:"column",gap:"14px"},children:goals.map(g=>{
      const pct=Math.min(100,Math.round((g.saved/g.target)*100));
      return o.jsxs("div",{style:{padding:"14px",borderRadius:"10px",background:"var(--card-h,rgba(15,23,42,.02))",border:"1px solid var(--line,rgba(15,23,42,.06))"},children:[
        o.jsxs("div",{style:{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"8px"},children:[
          o.jsxs("span",{style:{fontWeight:"600",fontSize:"14px",color:"var(--ink-1)"},children:[g.name]}),
          o.jsxs("span",{className:"anum",style:{fontSize:"13px",fontWeight:"600",color:pct>=100?"#10b981":"var(--ink-1)"},children:[cur,ke(g.saved)," / ",cur,ke(g.target)," (",pct,"%)"]})
        ]}),
        o.jsx("div",{style:{height:"7px",borderRadius:"4px",background:"var(--selected,rgba(15,23,42,.08))",overflow:"hidden",marginBottom:"10px"},children:o.jsx("div",{style:{width:`${pct}%`,height:"100%",background:pct>=100?"#10b981":g.color,transition:"width .3s"}})}),
        o.jsxs("div",{style:{display:"flex",justifyContent:"space-between",alignItems:"center"},children:[
          o.jsxs("div",{style:{display:"flex",gap:"6px"},children:[
            o.jsx("button",{style:{padding:"4px 8px",borderRadius:"6px",border:"1px solid var(--line,rgba(15,23,42,.15))",background:"var(--surface,#fff)",fontSize:"11px",cursor:"pointer"},onClick:()=>deposit(g.id,50),children:"+50"}),
            o.jsx("button",{style:{padding:"4px 8px",borderRadius:"6px",border:"1px solid var(--line,rgba(15,23,42,.15))",background:"var(--surface,#fff)",fontSize:"11px",cursor:"pointer"},onClick:()=>deposit(g.id,100),children:"+100"}),
            o.jsx("button",{style:{padding:"4px 8px",borderRadius:"6px",border:"1px solid var(--line,rgba(15,23,42,.15))",background:"var(--surface,#fff)",fontSize:"11px",cursor:"pointer",color:"var(--ink-3)"},onClick:()=>deposit(g.id,-50),children:"−50"})
          ]}),
          o.jsx("button",{style:{background:"transparent",border:"none",color:"#ef4444",fontSize:"11.5px",cursor:"pointer",padding:"4px"},onClick:()=>deleteGoal(g.id),children:"Supprimer"})
        ]})
      ]},g.id);
    })})
  ]});
}

